CREATE TABLE public.troubleshooting_issues (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  title text NOT NULL,
  keywords text,
  causes text,
  check_steps text,
  fix_steps text,
  ai_check_draft text,
  ai_fix_draft text,
  status text NOT NULL DEFAULT 'pending',
  asked_by text,
  sort_order int DEFAULT 100,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT, INSERT, UPDATE, DELETE ON public.troubleshooting_issues TO anon, authenticated;
GRANT ALL ON public.troubleshooting_issues TO service_role;

ALTER TABLE public.troubleshooting_issues ENABLE ROW LEVEL SECURITY;
CREATE POLICY "public read troubleshooting" ON public.troubleshooting_issues FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "public insert troubleshooting" ON public.troubleshooting_issues FOR INSERT TO anon, authenticated WITH CHECK (true);
CREATE POLICY "public update troubleshooting" ON public.troubleshooting_issues FOR UPDATE TO anon, authenticated USING (true) WITH CHECK (true);
CREATE POLICY "public delete troubleshooting" ON public.troubleshooting_issues FOR DELETE TO anon, authenticated USING (true);

INSERT INTO public.troubleshooting_issues (title, keywords, causes, check_steps, fix_steps, status, sort_order) VALUES
('เครื่องปั๊มลมไม่ทำงาน',
 'ไม่ทำงาน, สตาร์ทไม่ติด, กดสตาร์ทแล้วเงียบ, ไฟไม่เข้า, เครื่องดับ',
 'ระบบไฟฟ้า / ระบบป้องกัน (Overload, Emergency) / บอร์ดคอนโทรล',
 E'1. ตรวจเช็กไฟเมนเข้าเครื่อง 3 เฟส ต้องได้ 380V ครบทุกเฟส (วัดคู่ L1-L2, L2-L3, L1-L3)\n2. ตรวจเช็กเบรกเกอร์ตู้เมนและเบรกเกอร์หน้าเครื่องว่าทริปหรือไม่\n3. ตรวจเช็กปุ่ม Emergency Stop ว่าถูกกดค้างไว้หรือไม่\n4. ตรวจเช็กฟิวส์คอนโทรลและหม้อแปลงคอนโทรลว่ามีไฟออกปกติ\n5. ตรวจเช็กอุปกรณ์ป้องกัน Overload / Phase Protection ว่าตัดการทำงานอยู่หรือไม่\n6. ตรวจเช็กแรงดันลมในถังว่าสูงกว่าค่าตัดของเครื่อง (เครื่องจะไม่สตาร์ทถ้าลมเต็ม)\n7. ตรวจเช็กบอร์ดคอนโทรลว่ามีไฟโชว์ / มีรหัส Error ค้างอยู่หรือไม่',
 E'1. แก้ไขไฟเข้าให้ครบ 3 เฟส 380V หากขาดเฟสให้แจ้งช่างไฟฟ้าแก้ที่ตู้เมน\n2. รีเซ็ต/สับเบรกเกอร์ที่ทริปกลับเข้าตำแหน่ง ON\n3. บิดปลดปุ่ม Emergency Stop ออกแล้วกด Reset ที่หน้าจอ\n4. เปลี่ยนฟิวส์คอนโทรลที่ขาด และเช็กหม้อแปลงคอนโทรล\n5. กดรีเซ็ตอุปกรณ์ป้องกัน Overload / Phase Protection และตั้งค่ากระแสให้ตรงกับมอเตอร์\n6. ปล่อยลมในระบบให้แรงดันต่ำกว่าค่าแรงดันตัด (Cut-out) แล้วสั่งสตาร์ทใหม่\n7. เคลียร์รหัส Error ที่บอร์ดคอนโทรล หากยังไม่หายให้เปลี่ยนบอร์ด/แจ้งทีมเซอร์วิส',
 'published', 1),
('ปั๊มลมอัดลมไม่ขึ้น',
 'ลมไม่ขึ้น, แรงดันตก, อัดลมไม่ขึ้น, ลมอ่อน, ลมไม่พอ',
 'ปริมาณการใช้ลมมากเกินกำลังเครื่อง / Unloader หรือ Solenoid ไม่ทำงาน / ลมรั่วในไลน์ / เมนไลน์หรือไส้กรองตัน / ชุดควบคุมไม่ทำงาน',
 E'1. เทียบอัตราการใช้ลมหน้างานจริงกับกำลังผลิตลมของเครื่อง (CFM)\n2. ตรวจเช็กชุด Unloader / Inlet Valve ว่าเปิดสุดขณะโหลดหรือไม่\n3. ตรวจเช็ก Solenoid Valve ว่ามีไฟเข้าและมีเสียงทำงานหรือไม่\n4. เดินตรวจหาจุดลมรั่วตามข้อต่อ ท่อ วาล์ว และอุปกรณ์ปลายทาง (ฟังเสียง/ใช้น้ำสบู่)\n5. ตรวจเช็กไส้กรองอากาศ (Air Filter) และไส้กรองแยกน้ำมัน (Separator) ว่าตันหรือไม่\n6. ตรวจเช็กเมนไลน์ ไดร์เออร์ และฟิลเตอร์ปลายทางว่าตันหรือแรงดันตกคร่อมสูงผิดปกติ',
 E'1. ลดการใช้ลมพร้อมกัน หรือเพิ่มขนาด/จำนวนเครื่องให้พอกับการใช้งาน\n2. เปลี่ยนชุดซ่อมซีล Unloader / Inlet Valve ที่รั่วหรือค้าง\n3. เปลี่ยน Solenoid Valve หรือแก้ไขสายไฟคอนโทรลที่ขาด\n4. แก้ไขจุดรั่วทุกจุด ขันข้อต่อใหม่ พันเทปเกลียว เปลี่ยนสายลมที่เสื่อม\n5. เปลี่ยนไส้กรองอากาศและไส้กรองแยกน้ำมันตามรอบชั่วโมงการใช้งาน\n6. ล้าง/เปลี่ยนไส้กรองไลน์และตรวจสอบไดร์เออร์ให้ระบายน้ำได้ปกติ',
 'published', 2),
('มีกลิ่นไม่พึงประสงค์ในลมอัด',
 'กลิ่นเหม็น, กลิ่นน้ำมัน, ลมมีกลิ่น, กลิ่นไหม้',
 'น้ำมันหมดสภาพหรือไหม้ / น้ำมันหลุดไปกับลม / ฟิลเตอร์ตัน',
 E'1. ตรวจเช็กสีและกลิ่นน้ำมันหล่อลื่น (ดำคล้ำ/มีกลิ่นไหม้ = หมดสภาพ)\n2. ตรวจเช็กชั่วโมงการใช้งานน้ำมันเทียบรอบเปลี่ยนมาตรฐาน\n3. ตรวจเช็กระดับน้ำมันในถังแยก ต้องอยู่ระหว่างขีด MIN-MAX\n4. ตรวจเช็กไส้กรองแยกน้ำมัน (Oil Separator) ว่าตันหรือรั่ว\n5. ตรวจเช็กระบบท่อดูดน้ำมันกลับ (Scavenge Line):\n   3.1 ท่อดูดน้ำมันคดงอหรือหักพับหรือไม่\n   3.2 รูออริฟิสตันหรืออุดตันด้วยตะกอนหรือไม่\n   3.3 ตำแหน่งปลายท่อดูดอยู่ชิดก้นไส้กรองถูกต้องหรือไม่\n   3.4 มีรอยรั่วซึมตามข้อต่อท่อดูดหรือไม่\n   3.5 เช็กวาล์วกันกลับในไลน์ว่าทำงานปกติหรือไม่',
 E'1. เปลี่ยนถ่ายน้ำมันใหม่ทั้งระบบ พร้อมล้างคราบตะกอน\n2. เติมน้ำมันให้ได้ระดับมาตรฐาน ห้ามเติมเกินขีด MAX\n3. ใช้น้ำมันเกรดที่ผู้ผลิตกำหนด ห้ามผสมต่างเกรด\n4. เปลี่ยนไส้กรองแยกน้ำมัน (Oil Separator) ตามรอบมาตรฐาน\n5. ล้างทำความสะอาดท่อดูดน้ำมันและรูออริฟิส จัดท่อไม่ให้คดงอ\n6. เปลี่ยนไส้กรองอากาศและฟิลเตอร์ปลายทาง แล้วเดินเครื่องไล่กลิ่นก่อนใช้งานจริง',
 'published', 3),
('เครื่องปั๊มลมมีความร้อนสูงจนตัดการทำงาน',
 'ร้อนจัด, Overheat, อุณหภูมิสูง, เครื่องตัด, High Temp',
 'การถ่ายเทอากาศรอบเครื่องไม่ดี อุณหภูมิเกิน 46°C / ฝาตู้ปิดไม่สนิท / มอเตอร์ช็อต / น้ำมันเสื่อมสภาพ / รังผึ้ง (Cooler) สกปรก',
 E'1. วัดอุณหภูมิห้องรอบเครื่อง ต้องไม่เกิน 46°C\n2. ตรวจเช็กช่องลมเข้า-ออกของห้อง และพัดลมระบายอากาศว่าเพียงพอหรือไม่\n3. วัดอุณหภูมิลมเข้าและออกที่รังผึ้ง (Oil Cooler / After Cooler) เทียบผลต่าง\n4. ตรวจเช็กความสกปรกของรังผึ้งและตะแกรงกรองฝุ่น\n5. ตรวจเช็กระดับและสภาพน้ำมันหล่อลื่น\n6. ตรวจเช็กกระแสมอเตอร์ทั้ง 3 เฟสว่าสมดุลและไม่เกินพิกัด\n7. ตรวจเช็กฝาตู้/แผงกันเสียงว่าปิดสนิททุกบานหรือไม่',
 E'1. ติดตั้งพัดลมระบายอากาศ/ท่อดักลมร้อนออกนอกห้องให้อุณหภูมิต่ำกว่า 46°C\n2. เป่าทำความสะอาดรังผึ้งด้วยลมแรงดันจากด้านในออกด้านนอก\n3. ล้างรังผึ้งด้วยน้ำยาเคมี (Flushing / Blender) เมื่อมีคราบน้ำมันอุดตัน\n4. เปลี่ยนถ่ายน้ำมันและไส้กรองน้ำมันที่เสื่อมสภาพ\n5. ปิดฝาตู้และแผงกันเสียงให้สนิททุกบานเพื่อบังคับทิศทางลมเย็น\n6. ตรวจซ่อม/พันมอเตอร์ใหม่หากพบกระแสไม่สมดุลหรือขดลวดช็อต\n7. ทำความสะอาดตะแกรงกรองฝุ่นและตรวจเช็กพัดลมเครื่องให้หมุนเต็มรอบ',
 'published', 4);